package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// Record layout
type SalesRec struct { // 01 SALES-REC, 12 bytes
	SrId    string          // PIC X(4) @0 len=4
	SrSales decimal.Decimal // PIC 9(6)V99 @4 len=8
}

type TierTable struct { // 01 TIER-TABLE
	TierEntry struct {
		TierLimit decimal.Decimal // PIC 9(6)V99
		TierRate  decimal.Decimal // PIC 9V99
	}
}

// Working-storage
var WsEofFlag string = "N" // PIC X
var WsIdx int64 = 0        // PIC 9
var WsTier int64 = 0       // PIC 9
var WsComm decimal.Decimal = decimal.Zero // PIC 9(6)V99
var WsTotal decimal.Decimal = decimal.Zero // PIC 9(9)V99
var WsCount int64 = 0       // PIC 9(3)
var WsSalesEd string        // PIC ZZZ,ZZ9.99
var WsRateEd string         // PIC 9.99
var WsCommEd string         // PIC ZZZ,ZZ9.99
var WsTotalEd string        // PIC ZZZ,ZZZ,ZZ9.99

var tierLimits [4]decimal.Decimal
var tierRates [4]decimal.Decimal

var CurSalesRec SalesRec

var inputLines []string
var inputPos int

func fitDecimal(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if val.IsZero() {
		return val
	}
	sign := val.Sign()
	abs := val.Abs()
	intPartDec := abs.Truncate(0)
	intPartInt := intPartDec.IntPart()
	pow10 := int64(1)
	for i := 0; i < intDigits; i++ {
		pow10 *= 10
	}
	intMod := intPartInt % pow10
	if intMod < 0 {
		intMod = -intMod
	}
	fracPart := abs.Sub(intPartDec)
	resultAbs := decimal.New(intMod, 0).Add(fracPart)
	if sign < 0 {
		resultAbs = resultAbs.Neg()
	}
	return resultAbs
}

func formatUneditedInt(v int64, width int) string {
	pow := int64(1)
	for i := 0; i < width; i++ {
		pow *= 10
	}
	mod := v % pow
	if mod < 0 {
		mod = -mod
	}
	return fmt.Sprintf("%0*d", width, mod)
}

func formatEdited(val decimal.Decimal, picture string) string {
	dotPos := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotPos >= 0 {
		intPic = picture[:dotPos]
		fracPic = picture[dotPos+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigitCount := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigitCount++
		}
	}
	fracDigitCount := len(fracPic)

	absVal := val.Abs()
	intPartDec := absVal.Truncate(0)
	intPartInt := intPartDec.IntPart()
	pow10Int := int64(1)
	for i := 0; i < intDigitCount; i++ {
		pow10Int *= 10
	}
	intModInt := intPartInt % pow10Int
	if intModInt < 0 {
		intModInt = -intModInt
	}
	intDigitsStr := fmt.Sprintf("%0*d", intDigitCount, intModInt)

	fracPart := absVal.Sub(intPartDec)
	var fracDigitsStr string
	if fracDigitCount > 0 {
		powFrac := decimal.New(1, int32(fracDigitCount))
		fracScaled := fracPart.Mul(powFrac).Round(0)
		fracInt := fracScaled.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		// handle carry if fractional rounding overflowed (e.g. 0.999 -> 1.00)
		// though values are already rounded, keep safe
		if fracInt >= pow10Int && fracDigitCount > 0 {
			// not needed for this program, but handle
		}
		fracDigitsStr = fmt.Sprintf("%0*d", fracDigitCount, fracInt)
	}

	firstNonZero := intDigitCount // sentinel = all zero
	for i, ch := range intDigitsStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}

	var outInt strings.Builder
	digitIdx := 0
	emitted := false
	for _, picCh := range intPic {
		switch picCh {
		case 'Z':
			d := intDigitsStr[digitIdx]
			digitIdx++
			if digitIdx-1 < firstNonZero {
				outInt.WriteByte(' ')
			} else {
				outInt.WriteByte(d)
				emitted = true
			}
		case '9':
			d := intDigitsStr[digitIdx]
			digitIdx++
			outInt.WriteByte(d)
			emitted = true
		case ',':
			if emitted {
				outInt.WriteByte(',')
			} else {
				outInt.WriteByte(' ')
			}
		default:
			outInt.WriteByte(byte(picCh))
		}
	}
	if dotPos >= 0 {
		result := outInt.String() + "." + fracDigitsStr
		if val.Sign() < 0 {
			// simple sign handling: replace first leading space with '-'
			// not required for this program (all positive)
			b := []byte(result)
			for i, c := range b {
				if c == ' ' {
					continue
				}
				if i > 0 {
					b[i-1] = '-'
				} else {
					// prepend
					result = "-" + result
					return result
				}
				result = string(b)
				break
			}
		}
		return result
	}
	return outInt.String()
}

func parseSalesField(s string) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.Zero
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		d, _ := decimal.NewFromString(trimmed)
		return d.Shift(-2)
	}
	return decimal.New(n, -2)
}

func openSalesFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
			inputPos = 0
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		inputLines = []string{}
		inputPos = 0
		return
	}
	content := string(data)
	parts := strings.Split(content, "\n")
	if len(parts) > 0 && parts[len(parts)-1] == "" && len(content) > 0 && content[len(content)-1] == '\n' {
		parts = parts[:len(parts)-1]
	}
	for i, p := range parts {
		if len(p) > 0 && p[len(p)-1] == '\r' {
			parts[i] = p[:len(p)-1]
		}
	}
	inputLines = parts
	inputPos = 0
}

func initPara() {
	tierLimits[0] = decimal.RequireFromString("1000.00")
	tierRates[0] = decimal.RequireFromString("2.50")
	tierLimits[1] = decimal.RequireFromString("5000.00")
	tierRates[1] = decimal.RequireFromString("4.00")
	tierLimits[2] = decimal.RequireFromString("20000.00")
	tierRates[2] = decimal.RequireFromString("5.50")
	tierLimits[3] = decimal.RequireFromString("999999.99")
	tierRates[3] = decimal.RequireFromString("7.25")
}

func readPara() {
	if inputPos >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputPos]
	inputPos++
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	CurSalesRec.SrId = line[0:4]
	field := line[4:12]
	CurSalesRec.SrSales = parseSalesField(field)
}

func processPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && WsTier == 0; WsIdx++ {
		if CurSalesRec.SrSales.Cmp(tierLimits[WsIdx-1]) <= 0 {
			WsTier = WsIdx
		}
	}
	var rate decimal.Decimal
	if WsTier >= 1 && WsTier <= 4 {
		rate = tierRates[WsTier-1]
	} else {
		rate = decimal.Zero
	}
	product := CurSalesRec.SrSales.Mul(rate)
	commRaw := product.Shift(-2)
	commRounded := commRaw.Round(2)
	WsComm = fitDecimal(commRounded, 6, 2)
	WsTotal = fitDecimal(WsTotal.Add(WsComm), 9, 2)
	WsCount = (WsCount + 1) % 1000

	WsSalesEd = formatEdited(CurSalesRec.SrSales, "ZZZ,ZZ9.99")
	WsRateEd = formatEdited(rate, "9.99")
	WsCommEd = formatEdited(WsComm, "ZZZ,ZZ9.99")

	tierStr := formatUneditedInt(WsTier, 1)
	line := CurSalesRec.SrId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Fprintln(os.Stdout, line)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, line)
}

func mainPara() {
	initPara()
	openSalesFile()
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	summaryPara()
}

func main() {
	mainPara()
}
